// ─────────────────────────────────────────────────────────────
// PROVENANCE SCAN
// Cheap byte-level search for metadata a vision model cannot see:
// C2PA manifests, IPTC digital-source-type tags, generator signatures
// (Stable Diffusion / ComfyUI / Midjourney…) and camera EXIF.
// Absence of metadata proves nothing — most platforms strip it.
// ─────────────────────────────────────────────────────────────

export interface ProvenanceReport {
  /** Metadata explicitly declares the file was generated by AI. */
  declaresAI: boolean;
  /** Metadata declares AI was used to edit an otherwise real capture. */
  declaresAIEdit: boolean;
  generator: string | null;
  hasC2PA: boolean;
  cameraHint: string | null;
  notes: string[];
}

const GENERATOR_SIGNATURES: [RegExp, string][] = [
  [/Midjourney/i, "Midjourney"],
  [/DALL[·\-\s]?E/i, "DALL·E"],
  [/ChatGPT|OpenAI/i, "OpenAI / ChatGPT"],
  [/Stable\s?Diffusion/i, "Stable Diffusion"],
  [/Steps: \d+, Sampler: /, "Stable Diffusion (A1111 parameters)"],
  [/ComfyUI|"class_type"\s*:\s*"KSampler/, "ComfyUI"],
  [/NovelAI/i, "NovelAI"],
  [/Adobe Firefly/i, "Adobe Firefly"],
  [/Made with Google AI|Google Imagen|SynthID/i, "Google AI (Imagen / Gemini)"],
  [/black-forest-labs|FLUX\.1/i, "FLUX"],
  [/Leonardo\.Ai/i, "Leonardo.Ai"],
  [/Ideogram/i, "Ideogram"],
  [/ElevenLabs/i, "ElevenLabs"],
  [/Runway(ML| Gen)/i, "Runway"],
  [/\bSora\b/, "OpenAI Sora"],
];

const CAMERA_SIGNATURES = /\b(Apple|iPhone|SAMSUNG|Canon|NIKON|SONY|FUJIFILM|OLYMPUS|Panasonic|Xiaomi|HUAWEI|OPPO|LEICA|Pixel \d)\b/;

const HEAD_BYTES = 512 * 1024;
const TAIL_BYTES = 128 * 1024;

export function scanProvenance(buffer: Buffer): ProvenanceReport {
  const head = buffer.subarray(0, HEAD_BYTES).toString("latin1");
  const tail = buffer.length > HEAD_BYTES
    ? buffer.subarray(Math.max(HEAD_BYTES, buffer.length - TAIL_BYTES)).toString("latin1")
    : "";
  const text = head + tail;

  const report: ProvenanceReport = {
    declaresAI: false,
    declaresAIEdit: false,
    generator: null,
    hasC2PA: /c2pa/i.test(text),
    cameraHint: null,
    notes: [],
  };

  // IPTC DigitalSourceType vocabulary (also embedded in C2PA manifests).
  if (/compositeWithTrainedAlgorithmicMedia/.test(text)) {
    report.declaresAIEdit = true;
    report.notes.push("IPTC/C2PA metadata declares the image was edited with generative AI (compositeWithTrainedAlgorithmicMedia).");
  } else if (/trainedAlgorithmicMedia/.test(text)) {
    report.declaresAI = true;
    report.notes.push("IPTC/C2PA metadata declares the file as AI-generated (trainedAlgorithmicMedia).");
  }

  for (const [pattern, name] of GENERATOR_SIGNATURES) {
    if (pattern.test(text)) {
      report.generator = name;
      report.declaresAI = report.declaresAI || !report.declaresAIEdit;
      report.notes.push(`Embedded metadata names an AI generator: ${name}.`);
      break;
    }
  }

  if (report.hasC2PA) {
    report.notes.push("A C2PA content-credentials manifest is present.");
  }

  if (text.includes("Exif\0\0")) {
    const camera = head.match(CAMERA_SIGNATURES);
    if (camera) {
      report.cameraHint = camera[1];
      report.notes.push(`Camera EXIF metadata present (device: ${camera[1]}). EXIF can be forged, so treat it as weak evidence of a real capture.`);
    } else {
      report.notes.push("EXIF metadata present, but no camera make/model was recognized.");
    }
  }

  return report;
}
